import unittest
from ratelimit import SlidingWindowLimiter


class RetryAfter(unittest.TestCase):
    def test_retry_after_measures_from_oldest_in_window(self):
        lim = SlidingWindowLimiter(limit=3, window=10)
        for t in (1, 2, 3):
            self.assertTrue(lim.allow("k", t))
        self.assertAlmostEqual(lim.retry_after("k", 5), 6.0)

import unittest
import fourstream as fs


class Pack(unittest.TestCase):
    def test_pack_stream_order_with_equal_lengths(self):
        block = fs.pack((b"11", b"22", b"33", b"44"))
        self.assertEqual(block, b"\x02\x00\x02\x00\x02\x00" + b"11223344")

import unittest
from decimal import Decimal
from allocate import allocate


class Invariants(unittest.TestCase):
    def test_sum_equals_amount_for_many_shapes(self):
        cases = [
            ("1.00", [1, 1, 1]), ("0.07", [5, 3, 9, 1]), ("99.99", [7, 11, 13]),
            ("0.10", [1, 3]), ("3.33", [2, 2, 2, 2, 2, 2, 2]), ("1000.01", [1, 999]),
        ]
        for amount, weights in cases:
            result = allocate(amount, weights)
            self.assertEqual(sum(result), Decimal(amount), (amount, weights))
            self.assertEqual(len(result), len(weights))
